// Package web holds the HTTP handlers and the templates they render.
package web

import (
	"bytes"
	"context"
	"embed"
	"errors"
	"html/template"
	"io/fs"
	"log/slog"
	"net/http"
	"net/url"
	"strings"
	"time"

	"github.com/davidepedone/hausbuch/internal/page"
	"github.com/davidepedone/hausbuch/internal/user"
)

// static/app.css is generated by `make css` from styles.css; it is embedded when present.
//
//go:embed static templates
var files embed.FS

const sessionCookie = "hausbuch_session"

type server struct {
	users           *user.Store
	pages           *page.Store
	defaultLanguage string
	templates       map[string]*template.Template
	editors         *editors
}

// view is what every template gets: the signed-in user, if any, and the page's own data.
type view struct {
	User *user.User
	Data any
}

var funcs = template.FuncMap{
	"date":     func(t time.Time) string { return t.Local().Format("2 Jan 2006, 15:04") },
	"names":    joinNames,
	"day":      func(t time.Time) string { return t.Local().Format("2 Jan 2006") },
	"language": page.LanguageName,
	"pageURL":  pageURL,
	"types":    func() []page.Type { return page.Types },
}

// NewHandler returns the application's HTTP handler. Everything except signing in, static assets and the health
// check requires a session. New pages start in defaultLanguage.
func NewHandler(users *user.Store, pages *page.Store, defaultLanguage string) http.Handler {
	s := &server{users: users, pages: pages, defaultLanguage: defaultLanguage, templates: map[string]*template.Template{},
		editors: &editors{open: map[editorKey]*editor{}}}
	for _, name := range []string{"home", "login", "password", "page", "edit", "editing", "deleted", "history",
		"revision", "compare"} {
		s.templates[name] = template.Must(template.New(name).Funcs(funcs).
			ParseFS(files, "templates/layout.html", "templates/parts.html", "templates/"+name+".html"))
	}
	static, err := fs.Sub(files, "static")
	if err != nil {
		panic(err)
	}

	signedIn := http.NewServeMux()
	signedIn.HandleFunc("GET /{$}", s.home)
	signedIn.HandleFunc("GET /pages/new", s.newPage)
	signedIn.HandleFunc("POST /pages", s.createPage)
	signedIn.HandleFunc("GET /pages/{id}", s.viewPage)
	signedIn.HandleFunc("GET /pages/{id}/edit", s.editPage)
	signedIn.HandleFunc("POST /pages/{id}", s.savePage)
	signedIn.HandleFunc("POST /pages/{id}/delete", s.deletePage)
	signedIn.HandleFunc("POST /pages/{id}/restore", s.restorePage)
	signedIn.HandleFunc("GET /deleted", s.deletedPages)
	signedIn.HandleFunc("POST /preview", s.preview)
	signedIn.HandleFunc("POST /pages/skeleton", s.skeleton)
	signedIn.HandleFunc("POST /pages/{id}/editing", s.stillEditing)
	signedIn.HandleFunc("POST /pages/{id}/cancel", s.cancelEdit)
	signedIn.HandleFunc("GET /pages/{id}/history", s.history)
	signedIn.HandleFunc("GET /pages/{id}/revisions/{n}", s.revision)
	signedIn.HandleFunc("GET /pages/{id}/revisions/{n}/compare", s.compare)
	signedIn.HandleFunc("POST /pages/{id}/revisions/{n}/restore", s.restoreRevision)
	signedIn.HandleFunc("POST /logout", s.logout)
	signedIn.HandleFunc("GET /account/password", func(w http.ResponseWriter, r *http.Request) {
		s.render(w, r, http.StatusOK, "password", passwordData{})
	})
	signedIn.HandleFunc("POST /account/password", s.changePassword)

	mux := http.NewServeMux()
	mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, _ *http.Request) {
		_, _ = w.Write([]byte("ok"))
	})
	mux.Handle("GET /static/", http.StripPrefix("/static/", http.FileServerFS(static)))
	mux.HandleFunc("GET /login", s.loginPage)
	mux.HandleFunc("POST /login", s.login)
	mux.Handle("/", s.requireSession(signedIn))

	return http.NewCrossOriginProtection().Handler(mux)
}

type ctxKey struct{}

func currentUser(r *http.Request) *user.User {
	u, _ := r.Context().Value(ctxKey{}).(*user.User)
	return u
}

// requireSession lets through requests with a valid session, refreshing its cookie, and turns away the others
// before they reach routing, so that nothing is revealed about what exists.
func (s *server) requireSession(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		var sess user.Session
		c, err := r.Cookie(sessionCookie)
		if err == nil {
			sess, err = s.users.LookupSession(r.Context(), c.Value)
		}
		if err != nil {
			if !errors.Is(err, http.ErrNoCookie) && !errors.Is(err, user.ErrNoSession) {
				slog.Error("look up session", "err", err)
			}
			if r.Method == http.MethodGet {
				http.Redirect(w, r, "/login?next="+url.QueryEscape(r.URL.RequestURI()), http.StatusSeeOther)
			} else {
				http.Error(w, "Sign in first.", http.StatusUnauthorized)
			}
			return
		}
		setSessionCookie(w, r, sess)
		next.ServeHTTP(w, r.WithContext(context.WithValue(r.Context(), ctxKey{}, &sess.User)))
	})
}

func setSessionCookie(w http.ResponseWriter, r *http.Request, sess user.Session) {
	http.SetCookie(w, &http.Cookie{
		Name:     sessionCookie,
		Value:    sess.Token,
		Path:     "/",
		Expires:  sess.Expires,
		HttpOnly: true,
		SameSite: http.SameSiteLaxMode,
		Secure:   isHTTPS(r),
	})
}

// isHTTPS reports whether the browser reached us over HTTPS, directly or through a proxy terminating it. A forged
// header can only make the cookie Secure, which breaks the forger's own session over plain HTTP.
func isHTTPS(r *http.Request) bool {
	return r.TLS != nil || r.Header.Get("X-Forwarded-Proto") == "https"
}

type loginData struct {
	NoAccounts bool
	Error      string
	Username   string
	Next       string
}

func (s *server) loginPage(w http.ResponseWriter, r *http.Request) {
	s.renderLogin(w, r, http.StatusOK, loginData{Next: r.URL.Query().Get("next")})
}

func (s *server) renderLogin(w http.ResponseWriter, r *http.Request, status int, data loginData) {
	users, err := s.users.List(r.Context())
	if err != nil {
		s.fail(w, err)
		return
	}
	data.NoAccounts = len(users) == 0
	s.render(w, r, status, "login", data)
}

func (s *server) login(w http.ResponseWriter, r *http.Request) {
	username, password, next := r.PostFormValue("username"), r.PostFormValue("password"), r.PostFormValue("next")
	u, err := s.users.Authenticate(r.Context(), username, password)
	if errors.Is(err, user.ErrBadCredentials) {
		s.renderLogin(w, r, http.StatusUnauthorized,
			loginData{Error: "Invalid username or password.", Username: username, Next: next})
		return
	}
	if err != nil {
		s.fail(w, err)
		return
	}
	sess, err := s.users.CreateSession(r.Context(), u)
	if err != nil {
		s.fail(w, err)
		return
	}
	setSessionCookie(w, r, sess)
	http.Redirect(w, r, localPath(next), http.StatusSeeOther)
}

// localPath returns next if it is a path on this site, and "/" otherwise, so that the login form can't be used to
// send someone to another site.
func localPath(next string) string {
	u, err := url.Parse(next)
	if err != nil || u.Scheme != "" || u.Host != "" || !strings.HasPrefix(next, "/") ||
		strings.HasPrefix(next, "//") || strings.HasPrefix(next, `/\`) {
		return "/"
	}
	return next
}

func (s *server) logout(w http.ResponseWriter, r *http.Request) {
	if c, err := r.Cookie(sessionCookie); err == nil {
		if err := s.users.DeleteSession(r.Context(), c.Value); err != nil {
			s.fail(w, err)
			return
		}
	}
	http.SetCookie(w, &http.Cookie{Name: sessionCookie, Path: "/", MaxAge: -1, Expires: time.Unix(0, 0)})
	http.Redirect(w, r, "/login", http.StatusSeeOther)
}

type passwordData struct {
	Error   string
	Changed bool
}

func (s *server) changePassword(w http.ResponseWriter, r *http.Request) {
	current, password, repeat := r.PostFormValue("current"), r.PostFormValue("new"), r.PostFormValue("repeat")
	if password != repeat {
		s.render(w, r, http.StatusBadRequest, "password", passwordData{Error: "The two new passwords don't match."})
		return
	}
	err := s.users.ChangePassword(r.Context(), currentUser(r).ID, current, password)
	switch {
	case errors.Is(err, user.ErrBadCredentials):
		s.render(w, r, http.StatusBadRequest, "password", passwordData{Error: "The current password is wrong."})
	case errors.Is(err, user.ErrInvalid):
		s.render(w, r, http.StatusBadRequest, "password", passwordData{Error: "The new password must not be empty."})
	case err != nil:
		s.fail(w, err)
	default:
		s.render(w, r, http.StatusOK, "password", passwordData{Changed: true})
	}
}

// render executes a page into a buffer first, so that a template error becomes a clean 500 rather than half a page.
func (s *server) render(w http.ResponseWriter, r *http.Request, status int, name string, data any) {
	var buf bytes.Buffer
	if err := s.templates[name].ExecuteTemplate(&buf, "layout", view{User: currentUser(r), Data: data}); err != nil {
		s.fail(w, err)
		return
	}
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.WriteHeader(status)
	_, _ = buf.WriteTo(w)
}

// renderPart answers an HTMX request with one part, a template defined in the page's file, of a page.
func (s *server) renderPart(w http.ResponseWriter, name, part string, data any) {
	var buf bytes.Buffer
	if err := s.templates[name].ExecuteTemplate(&buf, part, data); err != nil {
		s.fail(w, err)
		return
	}
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	_, _ = buf.WriteTo(w)
}

func (s *server) fail(w http.ResponseWriter, err error) {
	slog.Error("request failed", "err", err)
	http.Error(w, "Something went wrong.", http.StatusInternalServerError)
}
